<script>
 import {currentEditorBusy,selectVersion,commitEditorEdit} from '../services/editor.js';
 import PropsPanel from './PropsPanel.svelte';
 import {keyboard} from '../lib/shortcuts.ts';
 import {autoDeskewSubject} from '../services/local-tools.js';
 import {layout,inspectorMax,saveLayout} from '../layout.svelte';import ResizeHandle from './ResizeHandle.svelte';
 import {Sun,Contrast,Droplets,Thermometer,RotateCcw,RotateCw,FlipHorizontal,FlipVertical,Eye,EyeOff,Lock,Undo2,Redo2,Check,Clock,ArrowUpRight,X} from 'lucide-svelte';
 import {studio,asset,isDirty,change,remember,undo,redo,run,save,notify} from '../studio.svelte';import {initialEdit,bytes} from '../api';import Histogram from './Histogram.svelte';
 import {slide} from 'svelte/transition';import {cubicOut} from 'svelte/easing';
 let {onclose,historyEnabled=true}=$props();const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 let numberCheckpoint='';
 let deskewStatus=$state('');
 async function automaticDeskew(){deskewStatus='正在识别主体轮廓和实际倾斜角度…';try{await autoDeskewSubject();deskewStatus='主体已自动摆正，已生成新版本；原图保留。';}catch(error){deskewStatus=error.message;}}
 function exactNumber(key,e){if(e.currentTarget.value===''||!e.currentTarget.validity.valid)return;if(numberCheckpoint!==key){remember();numberCheckpoint=key;}change({[key]:Number(e.currentTarget.value)},false);}
 const controls=[{key:'exposure',name:"曝光",icon:Sun,min:-3,max:3,step:.05},{key:'contrast',name:"对比度",icon:Contrast,min:0,max:3,step:.01},{key:'saturation',name:"饱和度",icon:Droplets,min:0,max:3,step:.01},{key:'temperature',name:"色温",icon:Thermometer,min:-1,max:1,step:.01}];
 const looks=[["原图",{}],["冷调",{contrast:1.2,saturation:.75,temperature:-.1}],["黑白",{contrast:1.14,saturation:0}],["鲜明",{contrast:1.14,saturation:1.3}],["暖光",{exposure:.2,temperature:.25}]];
 function crop(ratio){const a=asset();if(!a)return;if(!ratio){change({crop:null});return;}const r=a.width/a.height;if(r>ratio){const w=ratio/r;change({crop:[(1-w)/2,0,w,1]});}else{const h=r/ratio;change({crop:[0,(1-h)/2,1,h]});}}
</script>
<aside id="editor-inspector" aria-label="图片编辑面板" class="inspector" style:width={`${Math.min(layout.inspectorWidth,inspectorMax())}px`} inert={currentEditorBusy()||!studio.inspector} transition:slide={{axis:'x',duration:reducedMotion?0:120,easing:cubicOut}}>
 <ResizeHandle axis="width" bind:value={layout.inspectorWidth} min={220} max={inspectorMax()} label="右侧面板宽度" onfinish={saveLayout} reset={()=>layout.inspectorWidth=280}/>
 <div class="inspector-title"><h2>{studio.inspectorTab==='properties'?'图片属性':studio.inspectorTab==='history'?"历史版本":studio.inspectorTab==='layers'?"图层":studio.tool==='crop'?"裁切":studio.tool==='transform'?"旋转与翻转":"图片调整"}</h2><div class="inspector-title-actions"><button aria-label="重置编辑" title="重置编辑" disabled={!asset()} onclick={()=>change({...initialEdit})}><RotateCcw size={15}/></button><button aria-label="关闭右侧面板" title="关闭右侧面板" onclick={onclose}><X size={17}/></button></div></div>
 <div class="inspector-tabs"><button class:active={studio.inspectorTab==='properties'} onclick={()=>studio.inspectorTab='properties'}>属性</button><button class:active={studio.inspectorTab==='adjust'} onclick={()=>studio.inspectorTab='adjust'}>调色</button><button class:active={studio.inspectorTab==='layers'} onclick={()=>studio.inspectorTab='layers'}>图层</button><button disabled={!historyEnabled} class:active={studio.inspectorTab==='history'} onclick={()=>studio.inspectorTab='history'}>历史版本</button></div>
 <div class="inspector-scroll">
 {#if asset()}
 {#if studio.inspectorTab==='properties'}<PropsPanel/>
 {:else if studio.inspectorTab==='adjust'}
 {#if studio.tool==='crop'}<section><h3>宽高比</h3><div class="ratio-grid">{#each [["原图",0],['1:1',1],['3:2',1.5],['4:3',4/3],['4:5',.8],['16:9',16/9]] as [label,ratio]}<button onclick={()=>crop(ratio)}>{label}</button>{/each}</div><p class="hint">在画布上拖动，选择裁切范围。</p>{#if studio.draft.crop}<div class="field-grid">{#each ['X','Y',"宽度","高度"] as label,i}<label>{label}<input aria-label={`Crop ${label}`} type="number" step=".01" min="0" max="1" value={studio.draft.crop[i]} onchange={e=>{const c=[...studio.draft.crop];c[i]=Number(e.target.value);if(c[2]>0&&c[3]>0&&c[0]+c[2]<=1&&c[1]+c[3]<=1)change({crop:c});}}/></label>{/each}</div>{/if}</section>
 {:else if studio.tool==='transform'}<section><h3>方向</h3><button class="line-button full" aria-label="主体自动摆正" disabled={!!studio.busy||!asset()} onclick={automaticDeskew}>主体自动摆正（识别倾斜）</button><p class="hint" role="status">{deskewStatus||'本地OpenCV识别主体轮廓，纠正小角度倾斜；不只是90°旋转。'}</p><div class="transform-grid"><button onclick={()=>change({rotation:(studio.draft.rotation+270)%360})}><RotateCcw size={19}/>−90°</button><button onclick={()=>change({rotation:(studio.draft.rotation+90)%360})}><RotateCw size={19}/>+90°</button><button class:active={studio.draft.flipH} onclick={()=>change({flipH:!studio.draft.flipH})}><FlipHorizontal size={19}/>水平翻转</button><button class:active={studio.draft.flipV} onclick={()=>change({flipV:!studio.draft.flipV})}><FlipVertical size={19}/>垂直翻转</button></div></section>
 {:else}<section class="looks-section"><h3>图片风格</h3><div class="looks">{#each looks as [name,patch],i}<button onclick={()=>change({...initialEdit,strokes:studio.draft.strokes||[],crop:studio.draft.crop,rotation:studio.draft.rotation,flipH:studio.draft.flipH,flipV:studio.draft.flipV,...patch})}><img src={studio.thumbs[studio.aid]} alt="" style:filter={i===2?'grayscale(1)':i===3?'saturate(1.5)':i===4?'sepia(.4)':i===1?'contrast(1.3)':'none'}/><span>{name}</span></button>{/each}</div></section>{/if}
 <section class="sliders-section"><h3>亮度与颜色</h3>{#each controls as c}<div class="adjustment"><label for={c.key}><c.icon size={14}/>{c.name}</label><input class="numeric" aria-label={`${c.name}数值`} type="number" step={c.step} min={c.min} max={c.max} value={Number(studio.draft[c.key].toFixed(2))} onfocus={()=>numberCheckpoint=''} onblur={()=>numberCheckpoint=''} oninput={e=>exactNumber(c.key,e)}/><input id={c.key} aria-label={c.name} type="range" min={c.min} max={c.max} step={c.step} value={studio.draft[c.key]} onpointerdown={remember} use:keyboard={{keydown: e=>{if(e.key.startsWith('Arrow'))remember();}}} oninput={e=>change({[c.key]:Number(e.target.value)},false)}/></div>{/each}</section>
 {:else if studio.inspectorTab==='layers'}<section class="layers"><h3>图层</h3><div class="layer"><button aria-label="启用或关闭调色" onclick={()=>change({adjustmentEnabled:!studio.draft.adjustmentEnabled})}>{#if studio.draft.adjustmentEnabled}<Eye size={16}/>{:else}<EyeOff size={16}/>{/if}</button><span>颜色调整</span></div><label class="opacity-label">不透明度 <span>{Math.round(studio.draft.adjustmentOpacity*100)}%</span><input aria-label="调色强度" type="range" min="0" max="1" step=".01" value={studio.draft.adjustmentOpacity} onpointerdown={remember} oninput={e=>change({adjustmentOpacity:Number(e.target.value)},false)}/></label><div class="layer original"><Lock size={15}/><img src={studio.thumbs[studio.aid]} alt=""/><span>原图</span></div></section>
 {:else}<section class="versions"><div class="section-row"><h3>已保存版本</h3><button class="text-button" onclick={()=>commitEditorEdit()}>保存版本</button></div>{#each [...asset().versions].reverse() as v}<div class="version"><Clock size={14}/><div><b>{v.kind==='generated'?"AI 生成":v.kind==='local'?"本地处理":"编辑"}</b><small>{new Date(v.createdAt*1000).toLocaleString()}</small></div><button title="恢复此版本" aria-label={`Restore ${v.id}`} onclick={()=>selectVersion(v.id)}><RotateCcw size={14}/></button></div>{/each}{#if !asset().versions.length}<p class="hint">尚无保存版本</p>{/if}<button class="line-button full" onclick={()=>selectVersion(null)}>恢复原图</button></section>{/if}
 <section class="histogram"><div class="section-row"><h3>颜色分布图</h3><span>RGB</span></div><Histogram src={studio.preview}/><div class="histogram-scale"><span>0</span><span>128</span><span>255</span></div></section><section class="asset-details"><div><span>图片尺寸</span><b>{asset().width} × {asset().height}</b></div><div><span>原始文件</span><b>{bytes(asset().bytes)}</b></div><div><span>版本数</span><b>{asset().versions.length}</b></div></section>
 {:else}<div class="empty small">请选择图片</div>{/if}
 </div><div class="inspector-bottom"><button onclick={()=>studio.compare=!studio.compare} disabled={!asset()}><Eye size={15}/>原图与效果对比</button><div><button aria-label="撤销" disabled={!isDirty()&&!studio.history[studio.aid]?.length} onclick={undo}><Undo2 size={17}/></button><button aria-label="重做" disabled={!studio.redo[studio.aid]?.length} onclick={redo}><Redo2 size={17}/></button></div></div>
</aside>
